132	// A cut needs a plane through the object and a side to keep; a split needs
133	// more than one shell. Checked before anything is copied or changed.
134	CommandResult check_divide(const ModelObject& object, const DivideRequest& request)
135	{
136	    if (object.instances.empty())
137	        return CommandResult::failure(WorkspaceError::Refused, object.name + " has no instance to divide");
138	    if (object.is_cut())
139	        return CommandResult::failure(WorkspaceError::Refused,
140	                                      object.name + " was cut with connectors; divide it with the app's cut tool");
141	    if (request.mode == DivideRequest::Mode::Plane) {
142	        const Vec3d normal(request.normal[0], request.normal[1], request.normal[2]);
143	        if (normal.norm() < 1e-9)
144	            return CommandResult::failure(WorkspaceError::InvalidArgument, "A cut plane needs a normal");
145	        if (!request.keep_upper && !request.keep_lower)
146	            return CommandResult::failure(WorkspaceError::InvalidArgument, "A cut keeps the upper piece, the lower one, or both");
147	        const BoundingBoxf3 box = object.instance_bounding_box(0);
148	        const Vec3d unit = normal.normalized();
149	        const Vec3d point(request.point[0], request.point[1], request.point[2]);
150	        double below = 0, above = 0;
151	        for (int corner = 0; corner < 8; ++corner) {
152	            const Vec3d at((corner & 1) ? box.max.x() : box.min.x(), (corner & 2) ? box.max.y() : box.min.y(),
153	                           (corner & 4) ? box.max.z() : box.min.z());
154	            const double side = unit.dot(at - point);
155	            below = std::min(below, side);
156	            above = std::max(above, side);
157	        }
158	        if (below >= -1e-6 || above <= 1e-6)
159	            return CommandResult::failure(WorkspaceError::InvalidArgument, "That plane does not pass through " + object.name);
160	        return CommandResult::success();
161	    }
162	    std::size_t parts = 0;
163	    bool        splittable = false;
164	    for (const ModelVolume* volume : object.volumes)
165	        if (volume->is_model_part()) {
166	            ++parts;
167	            splittable = splittable || volume->is_splittable();
168	        }
169	    // Split to objects also separates the parts of a multi-part object.
170	    if (!splittable && !(parts > 1 && !request.as_parts))
171	        return CommandResult::failure(WorkspaceError::InvalidArgument, object.name + " is one shell and cannot be split");
172	    return CommandResult::success();
173	}
