void ToolExecutionCoordinator::notify(const ToolActivity& activity)
{
    // pump() announces this outcome once the save after it is done.
    if (!m_saving_after.empty() && activity.action_id == m_saving_after && tool_state_terminal(activity.state))
        return;
    std::shared_ptr<ObserverState> state = m_observers;
    std::vector<std::uint64_t> ids;
    ids.reserve(state->observers.size());
    for (const auto& observer : state->observers)
        ids.push_back(observer.first);

    // Look each observer up immediately before invocation so callbacks may
    // safely unsubscribe themselves or another observer during dispatch.
    for (const std::uint64_t id : ids) {
        if (!state->alive)
            break;
        const auto observer = state->observers.find(id);
        if (canvas == nullptr || !canvas->is_initialized()) {
            fail("The project canvas is not ready for a durable save");
            return {};
        }
        if (!capture(true))
            return {};
    }
    const std::string id = m_store->head_id();
    try {
        m_store->pin(id);
    } catch (const std::exception& error) {
        // Pinning writes into the project folder like any save, so a folder
        // that cannot be written is a failed save, reported and retried.
        fail(error.what());
        return {};
    }
    return id;
}

